import { useCallback, useState } from 'react';
import { Button, Calendar } from '@jinx-ui/react';

interface ReportDatePickerProps {
  initialDate?: Date;
  onChange?: (date: Date) => void;
}

function startOfDay(date: Date): Date {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  return d;
}

function addDays(date: Date, days: number): Date {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

function isSameDay(a: Date, b: Date): boolean {
  return a.getTime() === b.getTime();
}

const quickOptions: { label: string; resolve: () => Date }[] = [
  { label: 'Сегодня', resolve: () => startOfDay(new Date()) },
  { label: 'Вчера', resolve: () => addDays(startOfDay(new Date()), -1) },
  { label: 'Неделя назад', resolve: () => addDays(startOfDay(new Date()), -7) },
];

export default function ReportDatePicker({ initialDate, onChange }: ReportDatePickerProps) {
  const [selectedDate, setSelectedDate] = useState<Date>(() =>
    startOfDay(initialDate ?? new Date())
  );

  const handleChange = useCallback(
    (date: Date) => {
      const normalized = startOfDay(date);
      setSelectedDate(normalized);
      onChange?.(normalized);
    },
    [onChange]
  );

  return (
    <div className="jx-stack jx-gap-md" style={{ gap: 'var(--jx-space-md)' }}>
      <div
        className="jx-flex jx-gap-sm"
        role="group"
        aria-label="Быстрый выбор даты отчёта"
        style={{ display: 'flex', gap: 'var(--jx-space-sm)', flexWrap: 'wrap' }}
      >
        {quickOptions.map((option) => {
          const optionDate = option.resolve();
          const isActive = isSameDay(optionDate, selectedDate);
          return (
            <Button
              key={option.label}
              type="button"
              variant={isActive ? 'solid' : 'outline'}
              size="sm"
              aria-pressed={isActive}
              onClick={() => handleChange(optionDate)}
            >
              {option.label}
            </Button>
          );
        })}
      </div>
      <Calendar
        value={selectedDate}
        onChange={handleChange}
        aria-label="Календарь даты отчёта"
        className="jx-calendar"
      />
    </div>
  );
}

